/* Left terminal records: icon | name over detail | value over action.
   Three columns leave the record body room inside the ~450px drawer; this layer
   supersedes the four-column ledger grid for contract, drone, escort and
   procurement rows (crew rows keep --ledger-cols). */
:root { --ledger-record-cols: 24px minmax(0, 1fr) 124px; }

.panel-left .deck-tabs-header::before {
    white-space: nowrap;
