    text-overflow: ellipsis;
    letter-spacing: 0.04em;
}
.panel-left .deck-tabs-header::after {
    content: "[ ]  CYCLE TABS\A\\  HIDE DRAWER";
    white-space: pre;
    margin-top: auto;
    padding: 8px 4px 2px;
    border-top: 1px solid rgba(201, 163, 90, 0.16);
