.drone-card .drone-actions { grid-column: 3; grid-row: 2 / -1; flex-direction: column; }

.fleet-ship-card > .fleet-value { grid-column: 3; grid-row: 1; }
.fleet-ship-card > .ship-actions { grid-column: 3; grid-row: 2; flex-direction: row; }
.fleet-ship-card .ship-actions .btn-hud { flex: 1 1 0; min-width: 0; }

.fleet-procurement-row > .procurement-info { grid-column: 2; grid-row: 1 / -1; }
.procurement-info strong,
.procurement-info h4 { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fleet-procurement-row > .procurement-value { grid-column: 3; grid-row: 1; align-self: end; }
.fleet-procurement-row > .procurement-action,
.fleet-procurement-row > .depot-actions { grid-column: 3; grid-row: 2; align-self: start; }
.procurement-action {
    justify-content: center;
    min-height: 26px;
    border: 1px solid rgba(201, 163, 90, 0.35);
    color: var(--console-gold);
}
.fleet-procurement-row:disabled { opacity: 0.55; cursor: not-allowed; }
EOF
