"""Profile the VoidFarer cockpit: server snapshot cost and client render/frame cost in real Edge."""
import json
import statistics
import sys
import tempfile
import time
from pathlib import Path

PROJECT = Path(sys.argv[1]).resolve()
sys.path.insert(0, str(PROJECT))

from playwright.sync_api import sync_playwright  # noqa: E402

from voidfarer.engine import SimulationEngine  # noqa: E402
from voidfarer.server import VoidFarerHandler, start_background_server  # noqa: E402
from voidfarer.storage import StorageManager  # noqa: E402

engine = SimulationEngine(seed=42)
engine.orbit("sol_body_1")
samples = []
for _ in range(30):
    t = time.perf_counter()
    snap = engine.get_status_snapshot()
    samples.append((time.perf_counter() - t) * 1000)
payload = json.dumps(snap)
print(f"server snapshot: median {statistics.median(samples):.2f}ms max {max(samples):.2f}ms, json {len(payload)/1024:.0f} KB")
t = time.perf_counter()
for _ in range(30):
    json.dumps(snap)
print(f"json encode: {(time.perf_counter()-t)/30*1000:.2f}ms")
top = sorted(((k, len(json.dumps(v))) for k, v in snap.items()), key=lambda kv: -kv[1])[:10]
print("largest keys:", ", ".join(f"{k}={n/1024:.0f}KB" for k, n in top))

with tempfile.TemporaryDirectory() as tmp:
    storage = StorageManager(Path(tmp) / "save")
    handle = start_background_server(engine, storage, port=0)
    VoidFarerHandler.static_dir = PROJECT / "voidfarer" / "static"
    url = f"http://127.0.0.1:{handle.port}/"
    with sync_playwright() as pw:
        browser = pw.chromium.launch(channel="msedge", headless=True)
        page = browser.new_page(viewport={"width": 1920, "height": 1080})
        page.goto(url)
        page.wait_for_function("() => Boolean(window.cockpit)")
        page.evaluate("""() => {
            const c = window.cockpit;
            window.__prof = { hud: [], radar: [], longTasks: 0, longMs: 0, fetch: [] };
            const wrap = (name, bucket) => {
                const fn = c[name].bind(c);
                c[name] = (...args) => { const t = performance.now(); const r = fn(...args); window.__prof[bucket].push(performance.now() - t); return r; };
            };
            wrap("renderHUD", "hud");
            wrap("drawRadar", "radar");
            new PerformanceObserver(list => list.getEntries().forEach(e => { window.__prof.longTasks++; window.__prof.longMs += e.duration; }))
                .observe({ entryTypes: ["longtask"] });
            c.gameStarted = true; c.closeMainMenu(); c.refreshState(true);
        }""")
        page.wait_for_timeout(1500)

        def measure(label, seconds=4):
            page.evaluate("() => { const p = window.__prof; p.hud = []; p.radar = []; p.longTasks = 0; p.longMs = 0; }")
            frames = page.evaluate(f"""() => new Promise(done => {{
                const times = []; let last = performance.now(); const end = last + {seconds * 1000};
                const tick = now => {{ times.push(now - last); last = now; if (now < end) requestAnimationFrame(tick); else done(times); }};
                requestAnimationFrame(tick);
            }})""")
            p = page.evaluate("() => window.__prof")
            med = lambda xs: statistics.median(xs) if xs else 0
