"""Measure strip/terminal geometry and clipped content at each review viewport."""
import sys
import tempfile
from pathlib import Path

PROJECT = Path(sys.argv[1]).resolve()
sys.path.insert(0, str(PROJECT))

from playwright.sync_api import sync_playwright  # noqa: E402

from voidfarer.engine import SimulationEngine  # noqa: E402
from voidfarer.server import VoidFarerHandler, start_background_server  # noqa: E402
from voidfarer.storage import StorageManager  # noqa: E402

VIEWPORTS = {"short": (1280, 720), "laptop": (1366, 768), "desktop": (1920, 1080), "4k": (3840, 2160)}
SCRIPT = """() => {
    const box = sel => { const e = document.querySelector(sel); if (!e) return null; const r = e.getBoundingClientRect();
        return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; };
    const clipped = [];
    document.querySelectorAll('#hudCommandStrip .power-slider-row, #hudCommandStrip .skill-quick-chip, #hudCommandStrip button, #hudCommandStrip .flight-log-stream').forEach(el => {
        const r = el.getBoundingClientRect(); if (!r.width) return;
        let p = el.parentElement;
        while (p && p.id !== 'hudCommandStrip') {
            const s = getComputedStyle(p);
            if (s.overflow !== 'visible' || s.overflowY !== 'visible') {
                const pr = p.getBoundingClientRect();
                if (r.bottom > pr.bottom + 1 || r.right > pr.right + 1) { clipped.push((el.id || el.className || el.tagName).toString().slice(0, 30)); break; }
            }
            p = p.parentElement;
        }
    });
    const tc = document.querySelector('#panelLeft .terminal-content-stack');
    return { strip: box('#hudCommandStrip'), left: box('#panelLeft'), radar: box('.panel-center'),
             terminalContentH: tc ? Math.round(tc.getBoundingClientRect().height) : null,
             reactor: box('#panelReactor'), clipped,
             topbarOverlap: (() => { const s = document.querySelector('.vital-streak, #streakLabel, .streak-card'); return s ? s.className : null; })() };
}"""

with tempfile.TemporaryDirectory() as tmp:
    engine = SimulationEngine(seed=42)
    handle = start_background_server(engine, StorageManager(Path(tmp) / "save"), port=0)
    VoidFarerHandler.static_dir = PROJECT / "voidfarer" / "static"
    with sync_playwright() as pw:
        browser = pw.chromium.launch(channel="msedge", headless=True)
        for name, (w, h) in VIEWPORTS.items():
            page = browser.new_page(viewport={"width": w, "height": h})
            page.goto(f"http://127.0.0.1:{handle.port}/")
            page.wait_for_function("() => Boolean(window.cockpit)")
            page.evaluate("() => { const c = window.cockpit; c.gameStarted = true; c.closeMainMenu(); c.refreshState(true); c.switchRightTab('market'); }")
            page.wait_for_timeout(900)
            print(name, page.evaluate(SCRIPT))
            page.close()
        browser.close()
    handle.stop()

