        ctx.strokeStyle = "rgba(144, 190, 109, 0.9)";
        ctx.lineWidth = R * 0.14;
        ctx.beginPath(); ctx.ellipse(0, 0, R * 1.2, R * 0.38, -0.35, 0, Math.PI * 2); ctx.stroke();
        ctx.fillStyle = "#fff4d6";
        ctx.beginPath(); ctx.arc(0, 0, R * 0.22, 0, Math.PI * 2); ctx.fill();
    }

