        const shadow = ctx.createLinearGradient(x + dx, y + dy, x - dx, y - dy);
        shadow.addColorStop(0, "rgba(0, 0, 0, 0)");
        shadow.addColorStop(0.45, "rgba(0, 0, 0, 0.05)");
        shadow.addColorStop(1, "rgba(2, 4, 10, 0.78)");
